"use client";

import { useForm, type Resolver } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { SampleCategoryUpdateSchema } from "@/domains/sampleCategory/entities/schema";
import type { SampleCategoryUpdateFields } from "@/domains/sampleCategory/entities/form";
import type { SampleCategory } from "@/domains/sampleCategory/entities";
import { useUpdateSampleCategory } from "@/domains/sampleCategory/hooks/useUpdateSampleCategory";
import { SampleCategoryForm } from "./SampleCategoryForm";
import { useRouter } from "@/lib/unsavedGuard";
import { useToast, useLoadingToast } from "@/lib/toast";
import { err } from "@/lib/errors";
import { buildFormDefaultValues } from "@/lib/formSuite";
import { domainDisplay } from "@/domains/sampleCategory/entities/display";

type Props = {
  sampleCategory: SampleCategory;
  redirectPath?: string;
};

export default function EditSampleCategoryForm({ sampleCategory, redirectPath = "/" }: Props) {
  const methods = useForm<SampleCategoryUpdateFields>({
    resolver: zodResolver(SampleCategoryUpdateSchema) as Resolver<SampleCategoryUpdateFields>,
    mode: "onSubmit",
    shouldUnregister: false,
    defaultValues: buildFormDefaultValues(domainDisplay, sampleCategory) as SampleCategoryUpdateFields,
  });

  const router = useRouter();
  const { showToast } = useToast();
  const { trigger, isMutating } = useUpdateSampleCategory();

  useLoadingToast(isMutating, "更新中です…");

  const submit = async (data: SampleCategoryUpdateFields) => {
    try {
      await trigger({ id: sampleCategory.id, data });
      showToast("更新しました", "success");
      router.push(redirectPath);
    } catch (error) {
      showToast(err(error, "更新に失敗しました"), "error");
    }
  };

  return (
    <SampleCategoryForm
      methods={methods}
      onSubmitAction={submit}
      isMutating={isMutating}
      submitLabel="更新"
      onCancel={() => router.push(redirectPath)}
    />
  );
}
